import '../content/content_models.dart';

/// Bundled Noto Sans subsets (pubspec `fonts:`, generated by `tool/subset_fonts.py`) for the scripts the interface
/// fonts (Inter, Outfit) lack, by the script code of [CourseTrackInfo.primaryScript].
///
/// They hold every character the content bundle uses in those scripts. Without them the web engine downloads
/// fallback fonts from fonts.gstatic.com at runtime and draws Japanese kanji with Chinese forms unless the browser's
/// language is Japanese. On iOS and Android they come before the system fonts, which is harmless.
const scriptFontFamilies = <String, String>{
  'Arab': 'LQ Noto Sans Arabic',
  'Hebr': 'LQ Noto Sans Hebrew',
  'Deva': 'LQ Noto Sans Devanagari',
  'Kore': 'LQ Noto Sans KR',
  'Jpan': 'LQ Noto Sans JP',
  'Hans': 'LQ Noto Sans SC',
  'Hant': 'LQ Noto Sans TC',
};

/// The fallback order for interface text: scripts that cannot be confused first, then Japanese before Chinese.
final List<String> scriptFontFallback = scriptFontFamilies.values.toList(growable: false);

/// The fallback order for text in [track]'s script (its phrases, its native name): its own font first, so Han
/// characters shared by Japanese and Chinese take that language's forms.
List<String> fontFallbackFor(CourseTrackInfo track) {
  final own = scriptFontFamilies[track.primaryScript];
  if (own == null) return scriptFontFallback;
  return [
    own,
    for (final family in scriptFontFallback)
      if (family != own) family,
  ];
}
